package com.scalpatlas.app
fun main(){
  // Geometry fixture derived from the 686 x 1536 calculator screenshot.
  fun klabel(value:String,x:Int,y:Int,w:Int=16,h:Int=25)=LiveMartingalePreview637.VisualLabel(
    value,(x-w/2f)/686,(y-h/2f)/1536,(x+w/2f)/686,(y+h/2f)/1536)
  val keypad=listOf(klabel("Calculator",130,662,100),klabel("Istoric tranzacții",166,1002,164),
    klabel("$1.09",260,580,100,35),klabel("7",168,718),klabel("8",342,718),klabel("9",518,718),
    klabel("4",168,786),klabel("5",342,786),klabel("6",518,786),
    klabel("1",168,853),klabel("2",342,853),klabel("3",518,853),klabel("0",342,920))
  val layout=checkNotNull(LiveMartingalePreview637.calculatorLayout(keypad))
  check(layout.raw=="1.09" && layout.keys.size==12)
  check(kotlin.math.abs(layout.keys.getValue("DELETE").x-518f/686)<.01f)
  check(kotlin.math.abs(layout.keys.getValue(".").x-168f/686)<.01f)
  check(LiveMartingalePreview637.calculatorLayout(keypad.filter{it.text!="9"})==null)
  check(LiveMartingalePreview637.calculatorLayout(keypad+klabel("7",500,950))==null)
  check(LiveMartingalePreview637.calculatorLayout(keypad.filter{!it.text.startsWith("$")})==null)

  check(LiveMartingalePreview637.entryBalance(155897L,109L,155788L,155897L,true)==155788L)
  check(LiveMartingalePreview637.entryBalance(155897L,109L,155897L,155788L,true)==155788L)
  check(LiveMartingalePreview637.entryBalance(155897L,109L,155788L,155700L,true)==null)
  check(LiveMartingalePreview637.entryBalance(155897L,109L,155788L,155897L,false)==null)
  check(LiveMartingalePreview637.entryBalance(155897L,109L,155897L,155897L,true)==null)
  check(LiveMartingalePreview637.entryBalance(155897L,109L,155788L,null,true)==155788L)

  check(LiveMartingalePreview637.calculatorKeys("1.09",228L)?.map{it.key}==
    listOf("DELETE","DELETE","DELETE","DELETE","2",".","2","8"))
  check(LiveMartingalePreview637.calculatorKeys("2.28",109L)?.last()?.after=="1.09")
  check(LiveMartingalePreview637.calculatorKeys("1.09",109L)?.isEmpty()==true)
  check(LiveMartingalePreview637.calculatorKeys("1.09",999999L)==null)
  check(LiveMartingalePreview637.calculatorKeys("x",228L)==null)

  val p=LiveMartingalePreview637
  val pair="AED/CNY OTC"
  check(p.parse(listOf("AED/CNY OTC WIN Profit net: +1.00"),pair,109)?.let{p.next(109,it)}==109L)
  check(p.parse(listOf("AED/CNY OTC LOSS P/L: -1.09"),pair,109)?.let{p.next(109,it)}==228L)
  check(p.parse(listOf("AUD/USD OTC LOSS P/L: -1.09"),pair,109)==null)
  check(p.parse(listOf("AED/CNY OTC LOSS P/L: -0.10"),pair,109)==null)
  check(p.parse(listOf("AED/CNY OTC WIN Profit net: +1.00","AED/CNY OTC LOSS P/L: -1.09"),pair,109)==null)
  check(p.parse(listOf("AED/CNY OTC LOSS"),pair,109)==null)
  check(p.next(81950,LiveMartingalePreview637.Result(pair,-81950,false))==null)
  check(p.ladder.sum()==157244L)
  check(p.format(109)=="1,09")
  check(p.format(228)=="2,28")
  check(p.permitsEdit(109,228,109,157232,0,157232))
  check(!p.permitsEdit(109,228,109,157232,null,157232))
  check(!p.permitsEdit(109,228,109,157232,1,157232))
  check(!p.permitsEdit(109,228,109,157232,0,157231))
  check(!p.permitsEdit(109,228,228,157232,0,157232))
  check(!p.permitsEdit(109,228,109,200,0,200))
  check(!p.permitsEdit(109,null,109,157232,0,157232))
  fun label(t:String,x:Float,y:Float)=LiveMartingalePreview637.VisualLabel(t,x,y,x+.07f,y+.018f)
  val anchor=label("Suma",.51f,.72f)
  val amount=label("1.09",.53f,.75f)
  val other=label("55.45967",.84f,.35f)
  check(p.readDisplayedStake(listOf(anchor,amount,other))==109L)
  check(p.readDisplayedStake(listOf(anchor,label("2,28",.53f,.75f)))==228L)
  check(p.readDisplayedStake(listOf(amount,other))==null)
  check(p.readDisplayedStake(listOf(anchor,label("92%",.53f,.75f)))==null)
  check(p.readDisplayedStake(listOf(anchor,amount,label("2.28",.56f,.76f)))==null)
  check(p.readDisplayedStake(listOf(anchor,label("1.09",.10f,.75f)))==null)
  check(p.readDisplayedStake(listOf(anchor,label("1.09",.53f,.94f)))==null)
  val tab=label("Tranzacții",.075f,.916f)
  val badge=label("1",.20f,.890f).copy(right=.23f)
  check(p.readPositionHint(listOf(tab,badge)).positive==1)
  check(p.readPositionHint(listOf(tab)).positive==null)
  check(p.readPositionHint(listOf(badge)).tabSeen==false)
  check(p.parse(listOf("AED/CNY OTC DRAW P/L: +0.00"),pair,228)?.let{p.next(228,it)}==228L)
  val g=TradePause637()
  g.observe(1000,true)
  check(g.remaining(1000)==300000L)
  g.observe(3000,true)
  check(g.remaining(4000)==297000L)
  g.observe(300000,false,true);g.settle()
  check(g.remaining(300500)!=null)
  g.observe(302500,false,true)
  check(g.remaining(302500)==null && !g.isLocked())
  val h=TradePause637()
  h.observe(1000,true);h.observe(301000,false,true)
  check(h.remaining(304000)!=null)
  check(h.remaining(422000)!=null)
  h.observe(422000,false,true);h.observe(424500,false,true)
  check(h.remaining(424500)!=null && h.isLocked())
  h.settle()
  check(h.remaining(424500)==null && !h.isLocked())
  val k=TradePause637()
  k.observe(1000,true);k.observe(420000,true)
  check(k.remaining(422000)!=null)
  val m=TradePause637()
  m.observe(1000,true);m.observe(300000,false,true);m.settle()
  m.observe(300100,true);m.observe(301000,false,true);m.observe(303500,false,true)
  check(m.remaining(303500)!=null && m.isLocked())
  val blue=0xff0e6aa9.toInt()
  val dark=0xff212435.toInt()
  fun badgePixel(x:Int,y:Int):Int=if((x-148)*(x-148)+(y-1368)*(y-1368)<=13*13){
    if(x in 147..148 && y in 1364..1371)0xffeeeeee.toInt() else blue
  }else dark
  check(p.bluePositionBadge(686,1536,::badgePixel))
  check(!p.bluePositionBadge(686,1536){_,_->dark})
  check(!p.bluePositionBadge(686,1536){_,y->if(y in 1366..1370)blue else dark})
  check(!p.bluePositionBadge(686,1536){_,_->blue})
  val loss=p.settledBalance(pair,109,157014,156905,300000,true)
  check(loss?.net == -109L && p.next(109,loss)==228L)
  val win=p.settledBalance(pair,109,157014,157114,300000,true)
  check(win?.win==true && p.next(109,win)==109L)
  val draw=p.settledBalance(pair,228,157014,157014,300000,true)
  check(draw?.draw==true && p.next(228,draw)==228L)
  check(p.settledBalance(pair,109,157014,156905,299999,true)==null)
  check(p.settledBalance(pair,109,157014,156905,300000,false)==null)
  check(p.settledBalance(pair,109,157014,156904,300000,true)==null)
  // Replay the reported account-wide entry, even after a pair change.
  check(p.entryDebit(109,156905,156796,2000,true))
  check(!p.entryDebit(109,156905,156795,2000,true))
  check(!p.entryDebit(109,156905,156796,46000,true))
  check(!p.entryDebit(109,156905,156796,2000,false))
  check(!p.entryDebit(109,null,156796,2000,true))
  val replay=p.settledBalance("AUD/CAD OTC",109,156905,156796,305000,true)
  check(replay?.net==-109L && p.next(109,replay)==228L)
  for(i in 0 until p.ladder.lastIndex){
    val stake=p.ladder[i]
    check(p.next(stake,LiveMartingalePreview637.Result(pair,-stake,false))==p.ladder[i+1])
  }
  check(p.isTradesFooter("Tranzacții"))
  check(p.isTradesFooter("Tranzactii"))
  check(p.isTradesFooter("Tranzacții 1"))
  check(!p.isTradesFooter("Tranzacții finalizate"))
  check(p.readPositionHint(listOf(label("Tranzacții 1",.075f,.916f))).positive==1)
  val actual=p.settledBalance("AUD/CAD OTC",109,156796,156687,300000,true)
  check(actual?.net==-109L && p.next(109,actual)==228L)
  val header=label("1,566.78",.57f,.075f)
  check(p.readHeaderBalance(listOf(header, label("1.09",.53f,.75f)))==156678L)
  check(p.readHeaderBalance(listOf(label("1.566,78",.57f,.075f)))==156678L)
  check(p.readHeaderBalance(listOf(label("1566.78",.57f,.92f)))==null)
  check(p.readHeaderBalance(listOf(header,label("1,567.87",.58f,.10f)))==null)
  check(p.stableIdleSample(156787,109,156787,109,6200,true))
  check(!p.stableIdleSample(156787,109,156678,109,6200,true))
  check(!p.stableIdleSample(156787,109,156787,109,16000,true))
  check(!p.stableIdleSample(156787,109,156787,109,6200,false))
  val latch=LiveMartingalePreview637.EntryLatch("demo",109,156569,1000)
  check(!latch.verify("AUD/CAD OTC","demo",null,null,1000,true))
  check(!latch.verify("AUD/CAD OTC","demo",109,156460,3000,true))
  check(latch.verify("AUD/CAD OTC","demo",109,156460,4500,true))
  val wrong=LiveMartingalePreview637.EntryLatch("demo",109,156569,1000)
  check(!wrong.verify("AUD/CAD OTC","real",109,156460,3000,true))
  check(!wrong.verify("AUD/CAD OTC","demo",109,156461,4500,true))
  check(!wrong.verify("AUD/CAD OTC","demo",109,156460,5000,false))
  check(!wrong.verify("AUD/CAD OTC","demo",109,156460,47000,true))
  // A late debit must still belong to the early identified single order.
  val late=LiveMartingalePreview637.EntryLatch("demo",109,156242,1000)
  check(!late.verify(pair,"demo",109,null,3000,true))
  check(!late.verify(pair,"demo",109,156133,60000,true))
  check(late.verify(pair,"demo",109,156133,62000,true))
  val noEarly=LiveMartingalePreview637.EntryLatch("demo",109,156242,1000)
  check(!noEarly.verify(pair,"demo",109,156133,60000,true))
  check(!noEarly.verify(pair,"demo",109,156133,62000,true))
  val multi=LiveMartingalePreview637.EntryLatch("demo",109,156242,1000)
  check(!multi.verify(pair,"demo",109,null,3000,true))
  check(!multi.verify(pair,"demo",109,156133,4000,false,true))
  check(!multi.verify(pair,"demo",109,156133,60000,true))
  check(!multi.verify(pair,"demo",109,156133,62000,true))
  val changed=LiveMartingalePreview637.EntryLatch("demo",109,156242,1000)
  check(!changed.verify(pair,"demo",109,null,3000,true))
  check(!changed.verify("AUD/CAD OTC","demo",109,156133,60000,true))
  check(!changed.verify(pair,"demo",109,156133,62000,true))
  check(!changed.verify(pair,"demo",109,156133,64000,true))
  val timeout=LiveMartingalePreview637.EntryLatch("demo",109,156242,1000)
  check(!timeout.verify(pair,"demo",109,null,3000,true))
  check(!timeout.verify(pair,"demo",109,156133,272000,true))
  val marker=label("$"+"1.09",.54f,.45f)
  check(p.readActiveStake(listOf(marker,amount))==109L)
  check(p.readActiveStake(listOf(amount))==null)
  check(p.readActiveStake(listOf(marker,marker))==null)
  check(p.confirmedVisualBadge(false,null,null)==null)
  check(p.confirmedVisualBadge(true,null,null)==null)
  check(p.confirmedVisualBadge(false,1,109)==null)
  check(p.confirmedVisualBadge(true,1,null)==1)
  check(p.confirmedVisualBadge(true,null,109)==1)
  check(p.confirmedVisualBadge(true,2,109)==2)
  // A debit without a broker position must not start a trade pause.
  val noOrder=TradePause637()
  check(p.entryDebit(109,156569,156460,2000,true))
  noOrder.observe(2000,p.confirmedVisualBadge(false,null,null)!=null,true)
  check(noOrder.remaining(2000)==null)
  check(p.shouldPauseForBadge(true))
  check(!p.shouldPauseForBadge(false))
  check(!p.bluePositionBadge(686,1536){x,y->
    if((x-148)*(x-148)+(y-1368)*(y-1368)<=13*13)blue else dark})
  val activeOrder=TradePause637()
  activeOrder.observe(2000,p.shouldPauseForBadge(true))
  check(activeOrder.remaining(2000)==300000L)
  check(activeOrder.remaining(32000)==270000L)
  val digit=LiveMartingalePreview637.VisualLabel("1",.208f,.885f,.225f,.900f)
  check(p.readBadgeCount(listOf(digit))==1)
  check(p.readBadgeCount(listOf(digit.copy(top=.4f,bottom=.42f)))==null)
  check(p.readBadgeCount(listOf(digit,digit.copy(text="2")))==null)
  val readback=LiveMartingalePreview637.EditReadback(228,1000)
  check(!readback.observe(109,2000,true))
  check(!readback.observe(228,3000,true))
  check(!readback.observe(228,3500,true))
  check(readback.observe(228,4500,true))
  val unsafe=LiveMartingalePreview637.EditReadback(228,1000)
  check(!unsafe.observe(228,2000,false))
  check(!unsafe.observe(228,3500,true))
  check(!unsafe.observe(109,5000,true))
  check(!unsafe.observe(228,5500,true))
  check(unsafe.expired(13001))
  val unverified=TradePause637()
  unverified.observe(1000,true)
  for(at in 290000L..298000L step 2000L)unverified.observe(at,false,true)
  check(unverified.remaining(298000L)!=null)
  for(at in 300000L..308000L step 2000L)unverified.observe(at,false,true)
  check(unverified.remaining(308000L)!=null)
  for(at in 310000L..316000L step 2000L)unverified.observe(at,false,true)
  check(unverified.remaining(316000L)==null && unverified.releasedWithoutResult)
  unverified.observe(317000L,true)
  check(unverified.remaining(317000L)==300000L && !unverified.releasedWithoutResult)
  val stale=TradePause637()
  stale.observe(1000L,true);stale.observe(290000L,false,true)
  check(stale.remaining(310000L)!=null)
  val stillOpen=TradePause637()
  stillOpen.observe(1000L,true)
  for(at in 300000L..312000L step 2000L)stillOpen.observe(at,true)
  check(stillOpen.remaining(312000L)!=null)
  // Simulate OCR splitting the dollar symbol or thousands separator into elements.
  val fullBalance=label("1,562.24",.57f,.075f)
  check(p.readHeaderBalance(listOf(label("1,",.57f,.075f),label("562.24",.64f,.075f)),listOf(fullBalance))==null)
  val whole=fullBalance.copy(right=.79f,bottom=.10f)
  val fragment=label("562.24",.64f,.075f).copy(right=.78f)
  check(p.readHeaderBalance(listOf(fragment),listOf(whole))==156224L)
  check(p.readHeaderBalance(listOf(label("1, 561.15",.57f,.075f)))==156115L)
  check(p.readHeaderBalance(listOf(label("1 561,15",.57f,.075f)))==156115L)
  check(p.readHeaderBalance(listOf(label("1 56 1,15",.57f,.075f)))==null)
  check(p.readHeaderBalance(listOf(label("1,561.15 USD",.57f,.075f)))==156115L)
  check(p.readHeaderBalance(listOf(label("1,561.15",.57f,.075f)),listOf(whole))==null)
  check(p.readHeaderBalance(listOf(label("1,562",.57f,.075f),label(".24",.67f,.075f)),listOf(fullBalance))==156224L)
  check(p.readHeaderBalance(listOf(header),listOf(fullBalance))==null)
  check(p.readActiveStake(listOf(label("$",.50f,.34f),label("1.09",.54f,.34f)),listOf(label("$"+"1.09",.50f,.34f)))==109L)
  check(p.readActiveStake(listOf(marker),listOf(label("$"+"2.28",.54f,.45f)))==null)
  check(p.readDisplayedStake(listOf(anchor),listOf(amount))==109L)
  check(p.readDisplayedStake(listOf(anchor,amount),listOf(label("2.28",.53f,.75f)))==null)
  println("PASS: badge, exact entry, stake readback and independent navigation recovery")
}
